// QA joint source-gate acceptance (plugin-title-enrichment box 8.1, Tier 1):
// the dormant-source contract over the FULL production path — a REAL
// cmd/mellifera server subprocess (the qaSerialStartServer harness, which
// wires the production ModulePresentation closure whose enrich.ResolveGates
// resolution feeds the composer, the real enrich queue, and the real scan
// notify) running the REAL serial-scanner/serial-parser/frame-grabber/
// shikimori plugin subprocesses over a REAL fixture library, gated through
// the REAL PUT /libraries/{id}/sources/{plugin_id} endpoint:
//
//   - enriched_baseline (setup, fatal not subtest): the fixture's series row
//     enriches through serial-parser → shikimori (search leg over the stub
//     upstream), lands the full sources.shikimori namespace + _provenance +
//     _view + identifiers.shikimori_id, and the served display_name composes
//     the walk's RU pick — the "from" side of the flip, without which every
//     later assertion would pass vacuously,
//   - dormant_composes_next_source: with the library gate set, the served
//     display_name flips to the parser title (the walk's next leg) on the
//     series list AND detail, and the composed episode {title} follows —
//     never the dormant namespace's RU pick,
//   - dormant_retains_document_bytes: the stored document is byte-identical
//     across the gate write and repeated serves — the whole raw document
//     (subsuming sources.shikimori, _provenance, _view, identifiers; the wire
//     carries the stored bytes verbatim, INV3),
//   - dormant_excludes_derivation: a SECOND directory scanned under the gate
//     settles ready with NO shikimori namespace (the drain ran — the parser
//     landed — but the dormant source derived nothing, settlement unblocked)
//     and composes parser-only, the stub upstream sees ZERO further requests,
//     and the gated row's namespace survives the re-scan (derivedCarry).
//
// HERMETIC: the library root anchors under t.TempDir() and the shikimori
// upstream is pinned to the local stub (qaSerialStartServer's
// MELLIFERA_SHIKIMORI_UPSTREAM env) — no test byte reaches the network.
// Fixture identity constants are independent of every other qa fixture
// (no-coincidence discipline); the expected names re-derive from the shared
// grammar's season cut and the seed's RU-first language_preference — the
// non-empty russian pick is what makes the post-gate flip a sound
// discriminator (a gate leak would surface as the RU pick, never the title).
//
// Every helper is qaGate-prefixed to stay collision-free in package itest and
// shaped for box 8.2's reuse (TestSourceGateRestore boots the same joint).
package itest

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"
)

// Fixture identity constants. The trailing S01/S02 markers are the seasons
// the shared grammar cuts from the clean titles (the parser stamps them on
// the rows and the shikimori Match derives the same search keys); the anime
// ids sit far from every other fixture's assignment.
const (
	qaGateDirA     = "QA Gate Vault S01"
	qaGateDirB     = "QA Gate Ridge S02"
	qaGateEpA1Rel  = qaGateDirA + "/QA Gate Vault S01E01.mkv"
	qaGateEpA2Rel  = qaGateDirA + "/QA Gate Vault S01E02.mkv"
	qaGateEpB1Rel  = qaGateDirB + "/QA Gate Ridge S02E01.mkv"
	qaGateEpA3Rel  = qaGateDirA + "/QA Gate Vault S01E03.mkv" // restore tripwire A: scan-only discovery
	qaGateEpB2Rel  = qaGateDirB + "/QA Gate Ridge S02E02.mkv" // restore tripwire B: scan-only discovery
	qaGateTitleA   = "QA Gate Vault"                          // the season cut — parser title AND search key
	qaGateTitleB   = "QA Gate Ridge"                          // ditto for the gated scan
	qaGateRussianA = "Врата Куба"                             // the walk's RU pick — the pre-gate display
	qaGateRussianB = "Хребет Врат"                            // dir B's never-served RU pick
	qaGateIDa      = 4711                                     // row A's anime (search-selected)
	qaGateIDb      = 4712                                     // dir B's anime (must NEVER be fetched)
	qaGatePlugin   = "shikimori"                              // the gated source id
)

// qaGateUpstream is the per-test fake shikimori origin: it records every
// request and serves THIS fixture's search lists and by-id payloads (the
// shared qaSerialStartUpstream's fixed map knows none of these titles).
type qaGateUpstream struct {
	baseURL string
	mu      sync.Mutex
	seen    []qaSerialUpstreamReq
}

// qaGateAnime builds one upstream anime payload whose name EQUALS the derived
// search title (every existing stub fixture's shape — single candidate,
// selection deterministic by construction).
func qaGateAnime(id int, name, russian string, episodes int) map[string]any {
	return qaSerialAnime(id, name, russian, "tv", episodes, "2015-07-05", "7.8")
}

// qaGateStartUpstream starts the stub; its URL feeds the server env's
// MELLIFERA_SHIKIMORI_UPSTREAM (the plugin child bakes it into every fetch).
func qaGateStartUpstream(t *testing.T) *qaGateUpstream {
	t.Helper()
	s := &qaGateUpstream{}
	mux := http.NewServeMux()
	mux.HandleFunc(qaSerialUpstreamSearch, func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		list := map[string][]map[string]any{
			qaGateTitleA: {qaGateAnime(qaGateIDa, qaGateTitleA, qaGateRussianA, 12)},
			qaGateTitleB: {qaGateAnime(qaGateIDb, qaGateTitleB, qaGateRussianB, 24)},
		}[r.URL.Query().Get("search")]
		if list == nil {
			http.NotFound(w, r)
			return
		}
		qaSerialWriteJSON(t, w, list)
	})
	mux.HandleFunc(qaSerialUpstreamSearch+"/", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		e := map[string]map[string]any{
			"4711": qaGateAnime(qaGateIDa, qaGateTitleA, qaGateRussianA, 12),
			"4712": qaGateAnime(qaGateIDb, qaGateTitleB, qaGateRussianB, 24),
		}[strings.TrimPrefix(r.URL.Path, qaSerialUpstreamSearch+"/")]
		if e == nil {
			http.NotFound(w, r)
			return
		}
		qaSerialWriteJSON(t, w, e)
	})
	hs := httptest.NewServer(mux)
	t.Cleanup(hs.Close)
	s.baseURL = hs.URL
	return s
}

func (s *qaGateUpstream) record(r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seen = append(s.seen, qaSerialUpstreamReq{
		method: r.Method, path: r.URL.Path, query: r.URL.RawQuery, ua: r.Header.Get("User-Agent"),
	})
}

// requests snapshots the recorded upstream traffic.
func (s *qaGateUpstream) requests() []qaSerialUpstreamReq {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]qaSerialUpstreamReq(nil), s.seen...)
}

// qaGateJoint is one composed source-gate joint: the real server subprocess
// + the stub upstream + the gated serial library.
type qaGateJoint struct {
	srv    qaSerialServer
	client *http.Client
	token  string
	up     *qaGateUpstream
	lib    int64
}

// qaGateStartJoint boots the joint: the seven server-side binaries, the REAL
// cmd/mellifera subprocess (whose main.go wiring carries the production
// ModulePresentation closure — one batched prefs read resolved through
// enrich.ResolveGates — plus the real queue and the scan notify), and the
// serial library over root. The scan stays with the caller.
func qaGateStartJoint(t *testing.T, up *qaGateUpstream, root string) *qaGateJoint {
	t.Helper()
	tmp := t.TempDir()
	srv := qaSerialStartServer(t, qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-gate-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-gate-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-gate-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-gate-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-gate-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-gate-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-gate-grabber", "./plugins/frame-grabber"),
	}, up.baseURL, tmp, "qa-gate-admin-token")
	j := &qaGateJoint{
		srv:    srv,
		client: &http.Client{Timeout: httpTimeout},
		token:  "qa-gate-admin-token",
		up:     up,
	}
	j.lib = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, j.token, root, "QA Source Gate")
	return j
}

// qaGatePutLibraryGate writes the library-scope shikimori gate through the
// REAL endpoint (204 on success).
func qaGatePutLibraryGate(t *testing.T, j *qaGateJoint, enabled bool) {
	t.Helper()
	url := j.srv.baseURL + "/api/v1/libraries/" + strconv.FormatInt(j.lib, 10) + "/sources/" + qaGatePlugin
	if status := doRequest(t, j.client, http.MethodPut, url, j.token, map[string]bool{"enabled": enabled}, nil); status != http.StatusNoContent {
		t.Fatalf("PUT library gate enabled=%v: HTTP %d, want 204", enabled, status)
	}
}

