// qaGateAwaitEnrichedSeries polls until the row at rel settles ready with BOTH
// the serial-parser and shikimori namespaces landed, returning the row. The
// failure dump carries the raw document (its _stages carry a skipped stage's
// reason — the diagnosis surface).
func qaGateAwaitEnrichedSeries(t *testing.T, j *qaGateJoint, rel string) qaGateSeries {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		for _, sr := range qaGateSeriesList(t, j) {
			if sr.RelativePath != rel || sr.Status != "ready" {
				continue
			}
			doc := parseAsyncDoc(t, sr.Document)
			if doc.Sources["serial-parser"] != nil && doc.Sources[qaGatePlugin] != nil {
				return sr
			}
		}
		time.Sleep(probeInterval)
	}
	sr := qaGateSeriesByPath(t, j, rel)
	t.Fatalf("series %q: shikimori namespace never landed (status %s); doc:\n%s", rel, sr.Status, sr.Document)
	return qaGateSeries{}
}

// qaGateWriteVaultFixtures writes dir A (two episodes) under root.
func qaGateWriteVaultFixtures(t *testing.T, root string) {
	t.Helper()
	qaSerialMedia(t, filepath.Join(root, qaGateEpA1Rel))
	qaSerialMedia(t, filepath.Join(root, qaGateEpA2Rel))
}

// qaGateWriteRidgeFixtures writes dir B (one episode) under root — the
// directory the gated scan discovers.
func qaGateWriteRidgeFixtures(t *testing.T, root string) {
	t.Helper()
	qaSerialMedia(t, filepath.Join(root, qaGateEpB1Rel))
}

// TestSourceGateJoint is the dormant-source acceptance floor (spec scenario
// 5cc9472ed43c03d8): a shikimori-enriched series row under a set library gate
// composes nothing from the dormant namespace while the stored namespace,
// provenance, view, and identifiers stay byte-identical — and the gate holds
// into derivation (a fresh row scanned under the gate settles without it).
func TestSourceGateJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA source-gate joint: skips under -short (builds binaries + subprocesses)")
	}
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("QA source-gate joint needs %s on PATH (fixture generation + probing; INV4: optional binary): %v", bin, err)
		}
	}

	root := t.TempDir()
	qaGateWriteVaultFixtures(t, root)
	up := qaGateStartUpstream(t)
	j := qaGateStartJoint(t, up, root)

	// --- enriched_baseline: one scan, one search leg, the namespace lands ---
	res := scanLibrary(t, j.client, j.srv.baseURL, j.token, j.lib)
	if res.Discovered != 3 || res.Persisted != 3 {
		t.Fatalf("gate library: scan discovered=%d persisted=%d, want 3/3 (1 serial record + 2 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	srA := qaGateAwaitEnrichedSeries(t, j, qaGateDirA)
	baseline := append([]byte(nil), srA.Document...) // own the bytes

	// The baseline is the non-vacuousness proof: the walk composed the RU pick
	// BEFORE the gate, and every retained region exists with the stub's values.
	doc := parseAsyncDoc(t, baseline)
	title, _ := doc.Sources[qaGatePlugin]["title"].(map[string]any)
	if asyncStr(title, "russian") != qaGateRussianA || asyncStr(title, "romaji") != qaGateTitleA {
		t.Fatalf("sources.shikimori.title = %v, want {romaji:%s russian:%s}", title, qaGateTitleA, qaGateRussianA)
	}
	if asyncStr(doc.Provenance["title"], "plugin_id") != qaGatePlugin {
		t.Fatalf("_provenance.title = %v, want a shikimori entry", doc.Provenance["title"])
	}
	viewTitle := doc.View["title"]
	if asyncStr(viewTitle, "source") != qaGatePlugin {
		t.Fatalf("_view.title = %v, want a shikimori entry", doc.View["title"])
	}
	var rawDoc map[string]any
	if err := json.Unmarshal(baseline, &rawDoc); err != nil {
		t.Fatalf("decode baseline doc: %v", err)
	}
	ids, _ := rawDoc["identifiers"].(map[string]any)
	if got, _ := ids["shikimori_id"].(float64); int(got) != qaGateIDa {
		t.Fatalf("identifiers.shikimori_id = %v, want %d (the anchor)", ids["shikimori_id"], qaGateIDa)
	}
	served := qaGateSeriesList(t, j)
	if len(served) != 1 || served[0].Display != qaGateRussianA {
		t.Fatalf("pre-gate series display = %+v, want the walk's RU pick %q", served, qaGateRussianA)
	}
	for _, it := range qaGateListItems(t, j) {
		want := qaGateRussianA + " · S01E02"
		if it.RelativePath == qaGateEpA1Rel {
			want = qaGateRussianA + " · S01E01"
		}
		if it.Display != want {
			t.Fatalf("pre-gate item %q display = %q, want the composed RU %q", it.RelativePath, it.Display, want)
		}
	}
	if reqs := up.requests(); len(reqs) != 1 {
		t.Fatalf("upstream saw %d requests after the first drain, want exactly 1 (the search leg): %+v", len(reqs), reqs)
	}

	// THE GATE — the only mutation between the byte captures.
	qaGatePutLibraryGate(t, j, false)

	t.Run("dormant_composes_next_source", func(t *testing.T) {
		// The series flips to the parser title on BOTH surfaces — the walk
		// skipped the dormant namespace and floored to its next leg.
		for _, sr := range qaGateSeriesList(t, j) {
			if sr.Display != qaGateTitleA {
				t.Errorf("series list display under the gate = %q, want the parser title %q (never the dormant %q)", sr.Display, qaGateTitleA, qaGateRussianA)
			}
		}
		if got := qaGateSeriesDetail(t, j, srA.ID).Display; got != qaGateTitleA {
			t.Errorf("series detail display under the gate = %q, want %q", got, qaGateTitleA)
		}
		// The composed episode {title} follows the same floored chain.
		want := map[string]string{
			qaGateEpA1Rel: qaGateTitleA + " · S01E01",
			qaGateEpA2Rel: qaGateTitleA + " · S01E02",
		}
		for _, it := range qaGateListItems(t, j) {
			if it.Display != want[it.RelativePath] {
				t.Errorf("item %q display under the gate = %q, want the recomposed %q", it.RelativePath, it.Display, want[it.RelativePath])
			}
		}
	})

	t.Run("dormant_retains_document_bytes", func(t *testing.T) {
		// The whole stored document is byte-identical across the gate write —
		// subsuming sources.shikimori, _provenance, _view, identifiers (the
		// wire carries the stored bytes verbatim; INV3). Read twice: identity
		// holds across repeated serves, not one lucky read.
		for i := 0; i < 2; i++ {
			after := qaGateSeriesDetail(t, j, srA.ID).Document
			if !bytes.Equal(baseline, after) {
				t.Fatalf("serve %d: stored document changed under the gate:\nbefore: %s\nafter:  %s", i+1, baseline, after)
			}
		}
		if row := qaGateSeriesByPath(t, j, qaGateDirA); !bytes.Equal(baseline, row.Document) {
			t.Fatalf("list row's document changed under the gate:\nbefore: %s\nafter:  %s", baseline, row.Document)
		}
	})

	t.Run("dormant_excludes_derivation", func(t *testing.T) {
		// A fresh directory scanned UNDER the gate: the dormant source derives
		// nothing (no upstream hit for its title), the row settles ready
		// anyway (settle skips the gated source), and composition floors to
		// the parser title.
		qaGateWriteRidgeFixtures(t, root)
		res := scanLibrary(t, j.client, j.srv.baseURL, j.token, j.lib)
		if res.Discovered != 5 || res.Persisted != 5 {
			t.Fatalf("gated scan: discovered=%d persisted=%d, want 5/5 (dir A re-observed 3 + dir B's 1 record + 1 episode); warnings=%v",
				res.Discovered, res.Persisted, res.Warnings)
		}
		qaSerialWaitSettled(t, j.client, j.srv.baseURL, j.token, j.lib)
		srB := qaGateSeriesByPath(t, j, qaGateDirB)
		if srB.Status != "ready" {
			t.Fatalf("gated row never settled: status %q (a dormant source must not block settlement)", srB.Status)
		}
		docB := parseAsyncDoc(t, srB.Document)
		if docB.Sources[qaGatePlugin] != nil {
			t.Errorf("gated row carries sources.shikimori: %v (a dormant source must derive nothing)", docB.Sources[qaGatePlugin])
		}
		if docB.Sources["serial-parser"] == nil {
			t.Errorf("gated row lacks sources.serial-parser (the drain must still run the live sources); doc:\n%s", srB.Document)
		}
		if srB.Display != qaGateTitleB {
			t.Errorf("gated row display = %q, want the parser title %q (composition floors past the dormant source)", srB.Display, qaGateTitleB)
		}
		// The upstream stays silent: no search for the gated title, no refetch
		// of row A's carried namespace.
		if reqs := up.requests(); len(reqs) != 1 {
			t.Errorf("upstream saw %d requests after the gated scan, want still 1: %+v", len(reqs), reqs)
		}
		// Row A's namespace survives the re-scan (derivedCarry verbatim).
		docA := parseAsyncDoc(t, qaGateSeriesByPath(t, j, qaGateDirA).Document)
		titleA, _ := docA.Sources[qaGatePlugin]["title"].(map[string]any)
		if asyncStr(titleA, "russian") != qaGateRussianA {
			t.Errorf("row A sources.shikimori.title after re-scan = %v, want the retained %q", titleA, qaGateRussianA)
		}
	})
}

// qaGateSummary is the QA-local decode of GET /libraries/{id}/summary — the
// TRIPWIRE COUNT the restore box's no-rescan half reads. Items is the count of
// episode rows, and DISCOVERY IS SCAN-EXCLUSIVE: the enrich queue "never
// creates rows" (persistRow refreshes loaded rows only), so the count moves
// iff a scanner ran. (The summary's updated_at was considered and REJECTED as
// the seam: the wake's own pass legitimately persists the episode items —
// their (episode, shikimori) legs are skipped stages — episode documents
// never apply for the source — and each skip still PutItems the row,
// advancing the RFC3339Nano stamp. The stamp is queue-noisy; the count is
// not.)
type qaGateSummary struct {
	Items     int64  `json:"items"`
	UpdatedAt string `json:"updated_at"`
}

// qaGateLibrarySummary fetches the library's summary (the tripwire read).
func qaGateLibrarySummary(t *testing.T, j *qaGateJoint) qaGateSummary {
	t.Helper()
	var s qaGateSummary
	url := j.srv.baseURL + "/api/v1/libraries/" + strconv.FormatInt(j.lib, 10) + "/summary"
	if status := doRequest(t, j.client, http.MethodGet, url, j.token, nil, &s); status != http.StatusOK {
		t.Fatalf("library %d summary: HTTP %d, want 200", j.lib, status)
	}
	return s
}

// qaGateDeleteLibraryGate clears the library-scope gate through the REAL
// endpoint (204; the server-side delete is idempotent clear-to-inherit).
func qaGateDeleteLibraryGate(t *testing.T, j *qaGateJoint) {
	t.Helper()
	url := j.srv.baseURL + "/api/v1/libraries/" + strconv.FormatInt(j.lib, 10) + "/sources/" + qaGatePlugin
	if status := doRequest(t, j.client, http.MethodDelete, url, j.token, nil, nil); status != http.StatusNoContent {
		t.Fatalf("DELETE library gate: HTTP %d, want 204", status)
	}
}

// qaGateRequireDormant pins one settled row's dormant posture — the premise
// both restores start from: ready (a dormant source must not block
// settlement), the parser namespace landed, the gated namespace ABSENT, and
// the served display floored to the parser title.
func qaGateRequireDormant(t *testing.T, j *qaGateJoint, rel, parserTitle string) qaGateSeries {
	t.Helper()
	sr := qaGateSeriesByPath(t, j, rel)
	if sr.Status != "ready" {
		t.Fatalf("%s: status %q, want ready", rel, sr.Status)
	}
	doc := parseAsyncDoc(t, sr.Document)
	if doc.Sources["serial-parser"] == nil {
		t.Fatalf("%s: lacks sources.serial-parser (the live drain must still run); doc:\n%s", rel, sr.Document)
	}
	if doc.Sources[qaGatePlugin] != nil {
		t.Fatalf("%s: carries sources.shikimori under the gate: %v (a dormant source must derive nothing)", rel, doc.Sources[qaGatePlugin])
	}
	if sr.Display != parserTitle {
		t.Fatalf("%s: dormant display = %q, want the parser title %q", rel, sr.Display, parserTitle)
	}
	return sr
}

// qaGateRequireRestored pins the restored posture after a wake: the row
// carries the RE-DERIVED namespace with the stub's exact title fields, the
// provenance and view entries point back at the source, and the identifiers
// anchor landed — the full namespace, not a partial merge. Awaits the wake's
// async derive (the namespace lands after the 204 returns).
func qaGateRequireRestored(t *testing.T, j *qaGateJoint, rel string, animeID int, romaji, russian string) qaGateSeries {
	t.Helper()
	sr := qaGateAwaitEnrichedSeries(t, j, rel)
	doc := parseAsyncDoc(t, sr.Document)
	title, _ := doc.Sources[qaGatePlugin]["title"].(map[string]any)
	if asyncStr(title, "romaji") != romaji || asyncStr(title, "russian") != russian {
		t.Fatalf("%s: restored sources.shikimori.title = %v, want {romaji:%s russian:%s}", rel, title, romaji, russian)
	}
	if asyncStr(doc.Provenance["title"], "plugin_id") != qaGatePlugin {
		t.Fatalf("%s: restored _provenance.title = %v, want a shikimori entry", rel, doc.Provenance["title"])
	}
	if asyncStr(doc.View["title"], "source") != qaGatePlugin {
		t.Fatalf("%s: restored _view.title = %v, want a shikimori entry", rel, doc.View["title"])
	}
	var rawDoc map[string]any
	if err := json.Unmarshal(sr.Document, &rawDoc); err != nil {
		t.Fatalf("%s: decode restored doc: %v", rel, err)
	}
	ids, _ := rawDoc["identifiers"].(map[string]any)
	if got, _ := ids["shikimori_id"].(float64); int(got) != animeID {
		t.Fatalf("%s: restored identifiers.shikimori_id = %v, want %d", rel, ids["shikimori_id"], animeID)
	}
	return sr
}

// qaGateRequireItemDisplays asserts every served item's composed display
// against the want map keyed by relative path (count too — a missing or
// duplicated item is a failure, not a silent skip).
func qaGateRequireItemDisplays(t *testing.T, j *qaGateJoint, want map[string]string) {
	t.Helper()
	got := qaGateListItems(t, j)
	if len(got) != len(want) {
		t.Fatalf("items: %d served, want %d", len(got), len(want))
	}
	for _, it := range got {
		if it.Display != want[it.RelativePath] {
			t.Errorf("item %q display = %q, want %q", it.RelativePath, it.Display, want[it.RelativePath])
		}
	}
}

// TestSourceGateRestore is the restore-side acceptance floor (spec scenario
// 905754511525b27e): a row scanned UNDER the library gate settles without the
// shikimori namespace; clearing the gate (DELETE — clear-to-inherit) or
// flipping it back (PUT enabled=true) fires the queue's EXISTING Notify wake
// (design.md: "enable restores through the queue's existing wake" — no new
// lifecycle transition, no rescan), the missing namespace re-derives with
// exactly ONE upstream fetch, and the served display composes the restored
// source on the next read.
//
// The NO-RESCAN half is a TRIPWIRE on the item count (qaGateSummary): inside
// each restore window the test drops a well-formed episode file into the
// library root — discovery is scan-exclusive (the enrich queue never creates
// rows), so if the namespace "restored" via a rescan the tripwire would
// surface as a new item row. The tripwire is proven live IN-BAND: the test's
// ONE sanctioned scan (the gated dir-B scan) discovers the first tripwire
// immediately (items 2→4, alongside dir B's real episode) — the same
// discovery that stayed silent through both wakes.
//
// Upstream accounting (the stub records every request; one search leg per
// derive, single candidate → no by-id fetch): 0 under the dormant scan → 1
// after the DELETE restore (dir A's leg) → still 1 after the gated dir-B scan
// → exactly 2 after the PUT restore (dir B's leg; dir A's carried namespace
// is never refetched). Item-count ledger: 2 (dormant) → 2 across the DELETE
// wake (tripwire A undiscovered) → 4 after the one real scan (tripwire A + dir
// B's episode discovered) → 4 across the PUT wake (tripwire B undiscovered).
func TestSourceGateRestore(t *testing.T) {
	if testing.Short() {
		t.Skip("QA source-gate restore: skips under -short (builds binaries + subprocesses)")
	}
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("QA source-gate restore needs %s on PATH (fixture generation + probing; INV4: optional binary): %v", bin, err)
		}
	}

	root := t.TempDir()
	qaGateWriteVaultFixtures(t, root)
	up := qaGateStartUpstream(t)
	j := qaGateStartJoint(t, up, root)

	// --- dormant_setup (fatal, not subtest): the gate is set BEFORE any
	// enrichment, so the scan settles dir A WITHOUT the shikimori namespace —
	// the scenario's "rows lacking the source's namespace" premise, 8.1's
	// dir-B posture on the primary row. ---
	qaGatePutLibraryGate(t, j, false)
	if res := scanLibrary(t, j.client, j.srv.baseURL, j.token, j.lib); res.Discovered != 3 || res.Persisted != 3 {
		t.Fatalf("dormant scan: discovered=%d persisted=%d, want 3/3 (1 serial record + 2 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	qaSerialWaitSettled(t, j.client, j.srv.baseURL, j.token, j.lib)
	srA := qaGateRequireDormant(t, j, qaGateDirA, qaGateTitleA)
	qaGateRequireItemDisplays(t, j, map[string]string{
		qaGateEpA1Rel: qaGateTitleA + " · S01E01",
		qaGateEpA2Rel: qaGateTitleA + " · S01E02",
	})
	if reqs := up.requests(); len(reqs) != 0 {
		t.Fatalf("upstream saw %d requests under the dormant scan, want 0 (dormancy excludes derivation): %+v", len(reqs), reqs)
	}
	seamDormant := qaGateLibrarySummary(t, j)
	if seamDormant.Items != 2 {
		t.Fatalf("summary items = %d, want 2 (the episodes; the serial record is a series row)", seamDormant.Items)
	}

	t.Run("restore_via_delete_clear", func(t *testing.T) {
		// Tripwire A: a well-formed episode dropped into dir A inside the
		// no-scan window. The wake cannot create rows; a scan in this window
		// would persist it as a third item.
		qaSerialMedia(t, filepath.Join(root, qaGateEpA3Rel))

		// THE CLEAR: DELETE removes the library-scope row; the inherited
		// resolution is enabled, so the endpoint wakes the queue for this
		// library and the missing namespace re-derives — no scan.
		qaGateDeleteLibraryGate(t, j)
		qaGateRequireRestored(t, j, qaGateDirA, qaGateIDa, qaGateTitleA, qaGateRussianA)

		// Composition on read flips to the restored source: series list AND
		// detail, then the episode floor.
		for _, sr := range qaGateSeriesList(t, j) {
			if sr.Display != qaGateRussianA {
				t.Errorf("series list display after restore = %q, want the RU pick %q", sr.Display, qaGateRussianA)
			}
		}
		if got := qaGateSeriesDetail(t, j, srA.ID).Display; got != qaGateRussianA {
			t.Errorf("series detail display after restore = %q, want %q", got, qaGateRussianA)
		}
		qaGateRequireItemDisplays(t, j, map[string]string{
			qaGateEpA1Rel: qaGateRussianA + " · S01E01",
			qaGateEpA2Rel: qaGateRussianA + " · S01E02",
		})

		// Exactly ONE upstream fetch re-derived the namespace.
		if reqs := up.requests(); len(reqs) != 1 {
			t.Errorf("upstream saw %d requests after the DELETE restore, want exactly 1 (the search leg): %+v", len(reqs), reqs)
		}

		// NO scan call: the tripwire stayed undiscovered across the whole
		// restore window — the count is exactly the dormant capture's.
		if seam := qaGateLibrarySummary(t, j); seam.Items != seamDormant.Items {
			t.Errorf("item count moved across the DELETE wake: %d, want %d (tripwire %q must stay undiscovered — a scan in the restore window would have persisted it)",
				seam.Items, seamDormant.Items, qaGateEpA3Rel)
		}
	})

	t.Run("restore_via_put_enable", func(t *testing.T) {
		// The scenario's other branch: the gate flips back to enabled. Build
		// the fresh dormant row first: write the disable (a disable wakes
		// nothing), then scan dir B under it — dir A keeps its namespace and
		// re-floors to the parser title on the live read.
		qaGatePutLibraryGate(t, j, false)
		if sr := qaGateSeriesByPath(t, j, qaGateDirA); sr.Display != qaGateTitleA {
			t.Errorf("dir A display under the re-set gate = %q, want the parser title %q (the live gate re-floors composition; the namespace stays)", sr.Display, qaGateTitleA)
		}
		qaGateWriteRidgeFixtures(t, root)
		// The test's ONE sanctioned scan. It MUST discover tripwire A (still
		// sitting in dir A from the DELETE window) alongside dir B's real
		// episode — the in-band proof the tripwire is live: the SAME
		// discovery stayed silent through the DELETE wake above.
		if res := scanLibrary(t, j.client, j.srv.baseURL, j.token, j.lib); res.Discovered != 6 || res.Persisted != 6 {
			t.Fatalf("gated dir-B scan: discovered=%d persisted=%d, want 6/6 (dir A: record + 3 episodes incl tripwire A; dir B: record + 1 episode); warnings=%v",
				res.Discovered, res.Persisted, res.Warnings)
		}
		qaSerialWaitSettled(t, j.client, j.srv.baseURL, j.token, j.lib)
		qaGateRequireDormant(t, j, qaGateDirB, qaGateTitleB)
		qaGateRequireItemDisplays(t, j, map[string]string{
			qaGateEpA1Rel: qaGateTitleA + " · S01E01",
			qaGateEpA2Rel: qaGateTitleA + " · S01E02",
			qaGateEpA3Rel: qaGateTitleA + " · S01E03",
			qaGateEpB1Rel: qaGateTitleB + " · S02E01",
		})
		if reqs := up.requests(); len(reqs) != 1 {
			t.Errorf("upstream saw %d requests after the gated dir-B scan, want still 1 (a scan never fetches the gated source): %+v", len(reqs), reqs)
		}
		seamScanned := qaGateLibrarySummary(t, j)
		if seamScanned.Items != 4 {
			t.Fatalf("summary items after the dir-B scan = %d, want 4 (A/E01, A/E02, the discovered tripwire A/E03, B/E01)", seamScanned.Items)
		}

		// Tripwire B: dropped inside the PUT-restore window, same contract.
		qaSerialMedia(t, filepath.Join(root, qaGateEpB2Rel))

		// THE FLIP: PUT enabled=true wakes the queue; dir B (the only row
		// lacking the namespace) re-derives; dir A is never refetched.
		qaGatePutLibraryGate(t, j, true)
		qaGateRequireRestored(t, j, qaGateDirB, qaGateIDb, qaGateTitleB, qaGateRussianB)
		for _, sr := range qaGateSeriesList(t, j) {
			want := qaGateRussianA
			if sr.RelativePath == qaGateDirB {
				want = qaGateRussianB
			}
			if sr.Display != want {
				t.Errorf("series %q display after the PUT restore = %q, want %q", sr.RelativePath, sr.Display, want)
			}
		}
		qaGateRequireItemDisplays(t, j, map[string]string{
			qaGateEpA1Rel: qaGateRussianA + " · S01E01",
			qaGateEpA2Rel: qaGateRussianA + " · S01E02",
			qaGateEpA3Rel: qaGateRussianA + " · S01E03",
			qaGateEpB1Rel: qaGateRussianB + " · S02E01",
		})
		if reqs := up.requests(); len(reqs) != 2 {
			t.Errorf("upstream saw %d requests after the PUT restore, want exactly 2 (one search leg per restored row; dir A never refetched): %+v", len(reqs), reqs)
		}
		if seam := qaGateLibrarySummary(t, j); seam.Items != seamScanned.Items {
			t.Errorf("item count moved across the PUT wake: %d, want %d (tripwire %q must stay undiscovered — a scan in the restore window would have persisted it)",
				seam.Items, seamScanned.Items, qaGateEpB2Rel)
		}
	})
}
